--
-- Table structure for table `tbl_notification`
--

DROP TABLE IF EXISTS `tbl_notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_notification` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sendFrom` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sendTo` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `followId` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `body` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `response` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `notificationType` int DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `postId` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isSendTo` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=users,1=admin',
  `isRead` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=Unread,1=Read',
  `createdAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2512 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

