--
-- Table structure for table `tbl_orders`
--

DROP TABLE IF EXISTS `tbl_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int DEFAULT NULL,
  `order_summaryId` int DEFAULT NULL,
  `orderStatus` tinyint(1) DEFAULT '0' COMMENT '0= Pending	\r\n1= Confirmed\r\n2= Cancelled	\r\n3= Completed	\r\n4= Refunded',
  `totalAmount` int DEFAULT NULL,
  `paymentStatus` tinyint(1) NOT NULL DEFAULT '1',
  `shippingDetailed` longtext COLLATE utf8mb4_general_ci,
  `delivery_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=pending,1=Delivered',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=96843 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

