INSERT INTO `tbl_sweepstakes` VALUES (31,'YUKON MOOSE HUNT','2025-07-30 00:00:00','2025-11-01 00:00:00','Yukon Moose Hunt Sweepstakes\r\nExperience the adventure of a lifetime with Trophy Talk’s exclusive Yukon Moose Hunt Sweepstakes! Enter for your chance to win a professionally guided moose hunt in the breathtaking wilds of the Yukon—one of North America’s most legendary big game destinations.\r\n\r\nWhat’s Included:\r\nFully guided moose hunt with Midnightsun Outfitting\r\nAccommodations and meals in the Yukon wilderness\r\nAll necessary permits and tags\r\nTrophy care and field preparation\r\n\r\nHow It Works:\r\nGet one FREE entry and Purchase bundle packs for even better odds\r\nEvery entry supports the hunting community and helps bring more opportunities to passionate outdoorsmen\r\nWinners are drawn at random and announced via our app','\"{\\\"free_entry_pack_name\\\":\\\"ONE FREE ENTRY\\\",\\\"free_entry_pack_price\\\":\\\"0\\\",\\\"single_entry_pack_entries\\\":\\\"20\\\",\\\"single_entry_pack_price\\\":\\\"100\\\",\\\"ranger_bundle_entries\\\":\\\"60\\\",\\\"ranger_bundle_price\\\":\\\"250\\\",\\\"pathfinder_entries\\\":\\\"35\\\",\\\"pathfinder_price\\\":\\\"150\\\"}\"',NULL,'70000',1,'2025-07-14 11:45:50','2025-07-28 18:48:44'),(32,'YUKON CARIBOU HUNT','2025-07-30 00:00:00','2025-11-01 00:00:00','Yukon Caribou Hunt Sweepstakes\r\nEmbark on an unforgettable journey with Trophy Talk’s Yukon Caribou Hunt Sweepstakes! Enter for your chance to win a fully guided caribou hunt in the heart of the Yukon—home to some of the world’s most impressive woodland caribou.\r\n\r\nWhat’s Included:\r\nProfessionally guided caribou hunt with experienced Midnightsun Outfitting\r\nComfortable wilderness accommodations and hearty meals\r\nAll required hunting permits and tags\r\nTrophy care and field preparation\r\n\r\nHow It Works:\r\nGet one FREE entry and purchase bundle packs to boost your odds\r\nEvery entry helps support the hunting community and unlocks more epic adventures for outdoorsmen\r\nWinners are randomly selected and announced through our app’s admin panel','\"{\\\"free_entry_pack_name\\\":\\\"ONE FREE ENTRY\\\",\\\"free_entry_pack_price\\\":\\\"0\\\",\\\"single_entry_pack_entries\\\":\\\"25\\\",\\\"single_entry_pack_price\\\":\\\"100\\\",\\\"ranger_bundle_entries\\\":\\\"60\\\",\\\"ranger_bundle_price\\\":\\\"250\\\",\\\"pathfinder_entries\\\":\\\"30\\\",\\\"pathfinder_price\\\":\\\"150\\\"}\"',NULL,'40000',1,'2025-07-14 12:03:41','2025-08-05 11:28:58');
/*!40000 ALTER TABLE `tbl_sweepstakes` ENABLE KEYS */;
UNLOCK TABLES;

