--
-- Table structure for table `tbl_user_stories`
--

DROP TABLE IF EXISTS `tbl_user_stories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_user_stories` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int DEFAULT NULL,
  `postName` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `videoUrl` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `videoThumbnail` longtext COLLATE utf8mb4_general_ci,
  `imageUrl` longtext COLLATE utf8mb4_general_ci,
  `captions` longtext COLLATE utf8mb4_general_ci,
  `hasTags` longtext COLLATE utf8mb4_general_ci,
  `location` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `tagPeople` text COLLATE utf8mb4_general_ci,
  `audiance` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `mediaType` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0',
  `isExpire` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0=active,1=expire',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `videoDuration` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

