  `code` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `forgotPasswordOtp` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `fcmToken` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `socialId` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0',
  `isSignUpMe` int DEFAULT NULL,
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pushNotifications` tinyint(1) NOT NULL DEFAULT '1',
  `giveAwayAnnoucment` tinyint(1) NOT NULL DEFAULT '0',
