  `genToken` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `isPurchaseFreeSweepstacks` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
